"""Pylama TOML configuration."""

from __future__ import annotations

from typing import Any

try:
    import tomllib as toml_loader
except ModuleNotFoundError:  # pragma: no cover
    try:
        import tomli as toml_loader  # type: ignore
    except ModuleNotFoundError:  # pragma: no cover
        import toml as toml_loader  # type: ignore

from pylama.libs.inirama import Namespace as _Namespace


def _prepare_value(value: Any) -> Any:
    if isinstance(value, (list, tuple, set)):
        return ",".join(str(item) for item in value)
    if isinstance(value, bool):
        return int(value)
    return value


class Namespace(_Namespace):
    """Inirama-style wrapper for TOML config."""

    def parse(self, source: str, update: bool = True, **params):
        del update, params
        content = toml_loader.loads(source)
        tool = content.get("tool", {})
        pylama = dict(tool.get("pylama", {}))
        linters = pylama.pop("linter", {}) or {}
        files = pylama.pop("files", []) or []

        for name, value in pylama.items():
            self["pylama"][name] = _prepare_value(value)

        for linter, options in linters.items():
            if not isinstance(options, dict):
                continue
            for name, value in options.items():
                self[f"pylama:{linter}"][name] = _prepare_value(value)

        for file_params in files:
            if not isinstance(file_params, dict):
                continue
            path = file_params.get("path")
            if path is None:
                continue
            for name, value in file_params.items():
                if name == "path":
                    continue
                self[f"pylama:{path}"][name] = _prepare_value(value)

