"""Manage lint execution context."""

from __future__ import annotations

import ast
import os.path as op
import re
from argparse import Namespace
from copy import copy
from functools import lru_cache
from pathlib import Path
from tempfile import NamedTemporaryFile, mkdtemp
from typing import Any, Dict, List, Set

from pylama.errors import Error
from pylama.utils import read

MODELINE_RE = re.compile(
    r"^\s*#\s+(?:pylama:)\s*((?:[\w_]*=[^:\n\s]+:?)+)", re.I | re.M
).search
SKIP_PATTERN = re.compile(r"# *noqa\b", re.I).search


def _split_values(value: Any) -> Set[str]:
    if isinstance(value, str):
        return {item for item in value.split(",") if item}
    return {str(item) for item in value}


class RunContext:  # pylint: disable=R0902
    """Manage resources for a single lint run."""

    __slots__ = (
        "errors",
        "options",
        "skip",
        "ignore",
        "select",
        "linters",
        "linters_params",
        "filename",
        "_ast",
        "_from_stdin",
        "_source",
        "_tempfile",
        "_lines",
    )

    def __init__(self, filename: str, source: str | None = None, options: Namespace | None = None):
        self.errors: List[Error] = []
        self.options = options
        self.skip = False
        self.ignore: Set[str] = set()
        self.select: Set[str] = set()
        self.linters: List[str] = []
        self.linters_params: Dict[str, Dict[str, Any]] = {}

        self._ast = None
        self._from_stdin = source is not None
        self._source = source
        self._tempfile = None
        self._lines = None

        if options:
            if options.abspath:
                filename = op.abspath(filename)
            self.skip = bool(options.skip and any(ptrn.match(filename) for ptrn in options.skip))
            self.linters.extend(list(options.linters))
            self.ignore |= set(options.ignore)
            self.select |= set(options.select)
            self.linters_params.update(dict(options.linters_params))

            for mask, file_params in options.file_params.items():
                if mask.match(filename):
                    self.update_params(**file_params)

        self.filename = filename

        if not self.skip:
            modeline = MODELINE_RE(self.source)
            if modeline:
                values = modeline.group(1).split(":")
                self.update_params(**dict(value.split("=", 1) for value in values))

    def __enter__(self):
        return self

    def __exit__(self, etype, evalue, _traceback):
        if self._tempfile is not None:
            tmpfile = Path(self._tempfile)
            if tmpfile.exists():
                tmpfile.unlink()
            if tmpfile.parent.exists():
                tmpfile.parent.rmdir()

        if evalue is not None:
            if etype is IOError:
                self.push(text=f"{evalue}", number="E001")
            elif etype is UnicodeDecodeError:
                self.push(text=f"UnicodeError: {self.filename}", number="E001")
            elif etype is SyntaxError:
                self.push(lnum=evalue.lineno or 1, col=evalue.offset or 1, text=f"SyntaxError: {evalue.args[0]}")
            else:
                self.push(lnum=1, col=1, text=str(evalue))
                return False

        return True

    @property
    def source(self) -> str:
        if self._source is None:
            self._source = read(self.filename)
        return self._source

    @property
    def lines(self) -> List[str]:
        if self._lines is None:
            self._lines = self.source.splitlines(True)
        return self._lines

    @property
    def ast(self):
        if self._ast is None:
            self._ast = compile(self.source, self.filename, "exec", ast.PyCF_ONLY_AST)
        return self._ast

    @property
    def temp_filename(self) -> str:
        if not self._from_stdin:
            return self.filename

        if self._tempfile is None:
            file = NamedTemporaryFile(
                "w",
                encoding="utf-8",
                suffix=".py",
                dir=mkdtemp(prefix="pylama_"),
                delete=False,
            )
            file.write(self.source)
            file.close()
            self._tempfile = file.name
        return self._tempfile

    def update_params(self, ignore=None, select=None, linters=None, skip=None, **_):
        """Update general params from file configs or modelines."""
        if select:
            self.select |= _split_values(select)
        if ignore:
            self.ignore |= _split_values(ignore)
        if linters:
            self.linters = [name for name in (linters.split(",") if isinstance(linters, str) else linters) if name]
        if skip is not None:
            self.skip = bool(skip if isinstance(skip, bool) else int(skip))

    @lru_cache(42)
    def get_params(self, name: str) -> Dict[str, Any]:
        """Get params for a linter with the given name."""
        lparams = copy(self.linters_params.get(name, {}))
        for key in ("ignore", "select", "enable", "disable"):
            if key in lparams and not isinstance(lparams[key], set):
                lparams[key] = _split_values(lparams[key])

        aliased = dict(lparams)
        for key, value in list(lparams.items()):
            if "_" in key:
                aliased.setdefault(key.replace("_", "-"), value)
            if "-" in key:
                aliased.setdefault(key.replace("-", "_"), value)
        return aliased

    @lru_cache(42)
    def get_filter(self, name: str, key: str) -> Set[str]:
        """Get select or ignore from linter params."""
        return self.get_params(name).get(key, set())

    def push(self, filtrate: bool = True, **params):
        """Record an error."""
        err = Error(filename=self.filename, **params)
        number = err.number

        if err.lnum >= 1 and len(self.lines) >= err.lnum and SKIP_PATTERN(self.lines[err.lnum - 1]):
            return None

        if filtrate:
            for rule in self.select | self.get_filter(err.source, "select"):
                if number.startswith(rule):
                    return self.errors.append(err)

            for rule in self.ignore | self.get_filter(err.source, "ignore"):
                if number.startswith(rule):
                    return None

        return self.errors.append(err)

