"""
Inirama is a python module that parses INI files.
"""

from __future__ import annotations

import io
import logging
import re
from collections import OrderedDict

__version__ = "0.8.0"
__project__ = "Inirama"
__author__ = "Kirill Klenov <horneds@gmail.com>"
__license__ = "BSD"

NS_LOGGER = logging.getLogger("inirama")


class Scanner:
    """Split a code string on tokens."""

    def __init__(self, source, ignore=None, patterns=None):
        self.reset(source)
        if patterns:
            self.patterns = []
            for key, regexp in patterns:
                self.patterns.append((key, re.compile(regexp)))
        if ignore:
            self.ignore = ignore

    def reset(self, source):
        """Reset scanner state."""
        self.tokens = []
        self.source = source
        self.pos = 0

    def scan(self):
        """Scan source and grab tokens."""
        self.pre_scan()
        end = len(self.source)

        while self.pos < end:
            best_pat = None
            best_pat_len = 0

            for pat, regexp in self.patterns:
                match = regexp.match(self.source, self.pos)
                if match:
                    best_pat = pat
                    best_pat_len = len(match.group(0))
                    break

            if best_pat is None:
                raise SyntaxError(f"SyntaxError[@char {self.pos}: Bad token.]")

            if best_pat in self.ignore:
                self.pos += best_pat_len
                continue

            token = (
                best_pat,
                self.source[self.pos : self.pos + best_pat_len],
                self.pos,
                self.pos + best_pat_len,
            )
            self.pos = token[-1]
            self.tokens.append(token)

    def pre_scan(self):
        """Prepare source."""

    def __repr__(self):
        return "<Scanner: " + ",".join("{0}({2}:{3})".format(*t) for t in self.tokens[-5:]) + ">"


class INIScanner(Scanner):
    """Get tokens for INI."""

    patterns = [
        ("SECTION", re.compile(r"\[[^]]+\]")),
        ("IGNORE", re.compile(r"[ \r\t\n]+")),
        ("COMMENT", re.compile(r"[;#].*")),
        ("KEY_VALUE", re.compile(r"[^=\s]+\s*[:=].*")),
        ("CONTINUATION", re.compile(r".*")),
    ]

    ignore = ["IGNORE"]

    def pre_scan(self):
        escape_re = re.compile(r"\\\n[\t ]+")
        self.source = escape_re.sub("", self.source)


undefined = object()


class Section(OrderedDict):
    """Representation of an INI section."""

    def __init__(self, namespace, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.namespace = namespace

    def __setitem__(self, name, value):
        value = str(value)
        if value.isdigit():
            value = int(value)
        super().__setitem__(name, value)


class InterpolationSection(Section):
    """INI section with interpolation support."""

    var_re = re.compile(r"{([^}]+)}")

    def get(self, name, default=None):
        if name in self:
            return self[name]
        return default

    def __interpolate__(self, match):
        try:
            key = match.group(1).strip()
            return self.namespace.default.get(key) or self[key]
        except KeyError:
            return ""

    def __getitem__(self, name, raw=False):
        value = super().__getitem__(name)
        if not raw:
            sample = undefined
            while sample != value:
                try:
                    sample, value = value, self.var_re.sub(self.__interpolate__, value)
                except RuntimeError as exc:  # pragma: no cover
                    message = f"Interpolation failed: {name}"
                    NS_LOGGER.error(message)
                    raise ValueError(message) from exc
        return value

    def iteritems(self, raw=False):
        for key in self:
            yield key, self.__getitem__(key, raw=raw)

    items = iteritems


class Namespace:
    """Default class for parsing INI."""

    default_section = "DEFAULT"
    silent_read = True
    section_type = Section

    def __init__(self, **default_items):
        self.sections = OrderedDict()
        for key, value in default_items.items():
            self[self.default_section][key] = value

    @property
    def default(self):
        return self.sections.get(self.default_section, {})

    def read(self, *files, **params):
        for filename in files:
            try:
                with io.open(filename, encoding="utf-8") as file:
                    NS_LOGGER.info("Read from `%s`", file.name)
                    self.parse(file.read(), **params)
            except (IOError, TypeError, SyntaxError, io.UnsupportedOperation):
                if not self.silent_read:
                    NS_LOGGER.error("Reading error `%s`", filename)
                    raise

    def write(self, file):
        if isinstance(file, str):
            file = io.open(file, "w", encoding="utf-8")

        if not hasattr(file, "read"):
            raise AttributeError(f"Wrong type of file: {type(file)}")

        NS_LOGGER.info("Write to `%s`", file.name)
        for section in self.sections:
            file.write(f"[{section}]\n")
            for key, value in self[section].items():
                file.write(f"{key:15}= {value}\n")
            file.write("\n")
        file.close()

    def parse(self, source, update=True, **params):
        del params
        scanner = INIScanner(source)
        scanner.scan()

        section = self.default_section
        name = None

        for token in scanner.tokens:
            if token[0] == "KEY_VALUE":
                name, value = re.split("[=:]", token[1], maxsplit=1)
                name, value = name.strip(), value.strip()
                if not update and name in self[section]:
                    continue
                self[section][name] = value
            elif token[0] == "SECTION":
                section = token[1].strip("[]")
            elif token[0] == "CONTINUATION":
                if not name:
                    raise SyntaxError(f"SyntaxError[@char {token[2]}: Bad continuation.]")
                self[section][name] += "\n" + token[1].strip()

    def __getitem__(self, name):
        if name not in self.sections:
            self.sections[name] = self.section_type(self)
        return self.sections[name]

    def __contains__(self, name):
        return name in self.sections

    def __repr__(self):
        return f"<Namespace: {self.sections}>"


class InterpolationNamespace(Namespace):
    """Namespace with interpolation support."""

    section_type = InterpolationSection

