    def get_filter(self, name: str, key: str) -> Set[str]:
        """Get select or ignore from linter params."""
        return self.get_params(name).get(key, set())

    def push(self, filtrate: bool = True, **params):
        """Record an error."""
        err = Error(filename=self.filename, **params)
        number = err.number

        if err.lnum >= 1 and len(self.lines) >= err.lnum and SKIP_PATTERN(self.lines[err.lnum - 1]):
